#!/usr/bin/env python3
"""
Fetch USGS streamflow data and identify flooding events.
Flooding is determined by comparing streamflow to action/flood stage from NWS.
"""

import requests
import csv
from datetime import datetime, timedelta

# Read station IDs
with open('/root/data/michigan_stations.txt', 'r') as f:
    stations = [line.strip() for line in f if line.strip()]

print(f"Found {len(stations)} stations")

# Date range: April 1-7, 2025
start_date = "2025-04-01"
end_date = "2025-04-07"

flood_results = {}

# Try using instantaneous values instead of daily values (more likely to have data)
for station in stations:
    print(f"\nProcessing station {station}...")

    # First check if we can get flood stage from NWS AHPS
    flood_stage = None
    action_stage = None

    # Try NWS API
    nws_url = f"https://api.water.noaa.gov/nwps/v1/gauges/{station}"
    try:
        nws_response = requests.get(nws_url, timeout=10)
        if nws_response.status_code == 200:
            nws_data = nws_response.json()
            if 'flood' in nws_data:
                flood_info = nws_data.get('flood', {})
                if flood_info.get('stage'):
                    flood_stage = float(flood_info['stage'])
                if flood_info.get('action'):
                    action_stage = float(flood_info['action'])
                print(f"  NWS flood stage: {flood_stage}, action stage: {action_stage}")
    except Exception as e:
        pass

    # Get instantaneous gage height values (parameter 00065)
    url = f"https://waterservices.usgs.gov/nwis/iv/"
    params = {
        "format": "json",
        "sites": station,
        "startDT": start_date,
        "endDT": end_date,
        "parameterCd": "00065",  # Gage height
        "siteStatus": "all"
    }

    gage_heights_by_day = {}

    try:
        response = requests.get(url, params=params, timeout=30)
        data = response.json()

        if 'value' in data and 'timeSeries' in data['value'] and data['value']['timeSeries']:
            time_series = data['value']['timeSeries']
            values = time_series[0]['values'][0]['value']

            for v in values:
                if v['value'] and v['value'] != '-999999':
                    date = v['dateTime'][:10]
                    val = float(v['value'])
                    if date not in gage_heights_by_day:
                        gage_heights_by_day[date] = []
                    gage_heights_by_day[date].append(val)

            if gage_heights_by_day:
                print(f"  Got gage height data for {len(gage_heights_by_day)} days")

                # If we have flood stage, use it
                if flood_stage:
                    flood_days = 0
                    for date, heights in gage_heights_by_day.items():
                        max_height = max(heights)
                        if max_height >= flood_stage:
                            flood_days += 1
                            print(f"    {date}: max height {max_height} >= flood stage {flood_stage}")

                    if flood_days > 0:
                        flood_results[station] = flood_days
                        print(f"  FLOODING: {flood_days} days")
                else:
                    print(f"  No flood stage threshold available")
        else:
            print(f"  No instantaneous gage height data")

    except Exception as e:
        print(f"  Error getting gage height: {e}")

# If we didn't find much, let's also try the statistical service to get percentile thresholds
print("\n\n--- Trying statistical approach for stations without NWS thresholds ---")

for station in stations:
    if station in flood_results:
        continue  # Already found flooding

    # Get daily streamflow values
    url = f"https://waterservices.usgs.gov/nwis/dv/"
    params = {
        "format": "json",
        "sites": station,
        "startDT": start_date,
        "endDT": end_date,
        "parameterCd": "00060",  # Discharge
        "siteStatus": "all"
    }

    try:
        response = requests.get(url, params=params, timeout=30)
        data = response.json()

        if 'value' not in data or 'timeSeries' not in data['value'] or not data['value']['timeSeries']:
            continue

        time_series = data['value']['timeSeries']
        values = time_series[0]['values'][0]['value']

        daily_flows = {}
        for v in values:
            if v['value'] and v['value'] != '-999999':
                date = v['dateTime'][:10]
                daily_flows[date] = float(v['value'])

        if not daily_flows:
            continue

        print(f"\nStation {station}: Got discharge data for {len(daily_flows)} days")

        # Get statistical data for comparison (90th percentile as flood threshold)
        # Use the stat service to get percentiles
        stat_url = f"https://waterservices.usgs.gov/nwis/stat/"
        stat_params = {
            "format": "json",
            "sites": station,
            "statReportType": "daily",
            "statTypeCd": "P90",  # 90th percentile
            "parameterCd": "00060"
        }

        try:
            stat_response = requests.get(stat_url, params=stat_params, timeout=30)
            stat_data = stat_response.json()

            if 'value' in stat_data and 'timeSeries' in stat_data['value'] and stat_data['value']['timeSeries']:
                stat_values = stat_data['value']['timeSeries'][0]['values'][0]['value']

                # Create lookup of P90 by day of year
                p90_by_day = {}
                for sv in stat_values:
                    month_day = sv.get('dateTime', '')
                    if month_day and sv['value'] and sv['value'] != '-999999':
                        p90_by_day[month_day] = float(sv['value'])

                if p90_by_day:
                    flood_days = 0
                    for date, flow in daily_flows.items():
                        # Convert date to month-day format
                        month_day = datetime.strptime(date, "%Y-%m-%d").strftime("2020-%m-%d")
                        if month_day in p90_by_day:
                            if flow > p90_by_day[month_day]:
                                flood_days += 1
                                print(f"  {date}: {flow} > P90 {p90_by_day[month_day]}")

                    if flood_days > 0:
                        flood_results[station] = flood_days
                        print(f"  HIGH FLOW: {flood_days} days above P90")
        except Exception as e:
            pass

    except Exception as e:
        pass

print(f"\n\n=== SUMMARY ===")
print(f"Found {len(flood_results)} stations with flooding/high flow conditions")

# Write results to CSV
import os
os.makedirs('/root/output', exist_ok=True)

with open('/root/output/flood_results.csv', 'w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['station_id', 'flood_days'])
    for station_id, flood_days in sorted(flood_results.items()):
        writer.writerow([station_id, flood_days])

print(f"Results written to /root/output/flood_results.csv")

